INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist GET die einzige Methode in REST?', 2, '[{"text": "Nein", "correct": true, "because": "POST, PUT, DELETE existieren"}, {"text": "Ja", "correct": false, "because": "Mehrere Methoden verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer POST-Anfrage?', 3, '[{"text": "Daten an Server senden", "correct": true, "because": "Erstellt oder aktualisiert"}, {"text": "Daten abrufen", "correct": false, "because": "Für GET geeignet"}, {"text": "UI anpassen", "correct": false, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zu REST?', 5, '[{"text": "GET", "correct": true, "because": "Ruft Daten ab"}, {"text": "POST", "correct": true, "because": "Sendet Daten"}, {"text": "DESIGN", "correct": false, "because": "Kein HTTP-Methode"}, {"text": "STYLE", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) GET ist idempotent. b) POST ist für Datenabrufe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "POST sendet Daten"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer REST-Anfrage?', 4, '[{"text": "HTTP-Methode", "correct": false, "because": "Definiert Aktion"}, {"text": "Endpunkt", "correct": false, "because": "Ziel der Anfrage"}, {"text": "Farbschema", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob JSON immer für REST genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "XML oder Text möglich"}, {"text": "Ja", "correct": false, "because": "Format flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Daten abzurufen?', 3, '[{"text": "GET", "correct": true, "because": "Holt Daten vom Server"}, {"text": "POST", "correct": false, "because": "Sendet Daten"}, {"text": "PUT", "correct": false, "because": "Aktualisiert Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat JSON in REST?', 5, '[{"text": "Leichtgewichtig", "correct": true, "because": "Einfach zu parsen"}, {"text": "Strukturiert", "correct": true, "because": "Key-Value-Paare"}, {"text": "Binärformat", "correct": false, "because": "Textbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) GET hat keine Body-Daten. b) POST ist idempotent. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "POST nicht idempotent"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine REST-Anfrage?', 4, '[{"text": "URL", "correct": false, "because": "Definiert Endpunkt"}, {"text": "HTTP-Methode", "correct": false, "because": "Steuert Aktion"}, {"text": "Grafikeditor", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist GET für große Datenmengen ideal?', 2, '[{"text": "Nein", "correct": true, "because": "URL-Länge begrenzt"}, {"text": "Ja", "correct": false, "because": "POST besser geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet REST mit JSON?', 4, '[{"text": "Lesbarkeit", "correct": true, "because": "Klar strukturiert"}, {"text": "Interoperabilität", "correct": true, "because": "Weit verbreitet"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass POST nur für Formulare ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für API-Daten"}, {"text": "Ja", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer GET-Anfrage?', 3, '[{"text": "Korrekter Endpunkt", "correct": true, "because": "Sichert Datenabruf"}, {"text": "Schnelle Antwort", "correct": false, "because": "Korrektheit zählt"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) JSON ist textbasiert. b) GET ändert Serverdaten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "GET ist idempotent"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei REST?', 5, '[{"text": "Datenlecks", "correct": true, "because": "Ohne Verschlüsselung"}, {"text": "Falsche Methodenwahl", "correct": true, "because": "Kann Logik stören"}, {"text": "Schnellere Antwort", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer POST-Anfrage unwichtig?', 3, '[{"text": "Datenformat", "correct": false, "because": "Muss kompatibel sein"}, {"text": "Endpunkt", "correct": false, "because": "Ziel definiert"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann GET Parameter im Body haben?', 3, '[{"text": "Nein", "correct": true, "because": "Parameter in URL"}, {"text": "Ja", "correct": false, "because": "Nicht REST-konform"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob POST immer JSON nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Form-Daten möglich"}, {"text": "Ja", "correct": false, "because": "Format flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Ressourcen zu erstellen?', 4, '[{"text": "POST", "correct": true, "because": "Sendet Daten zur Erstellung"}, {"text": "GET", "correct": false, "because": "Nur Abruf"}, {"text": "DELETE", "correct": false, "because": "Löscht Ressourcen"}]');
